import json,torch
U=W('lm_head.weight'); nw=W('model.language_model.norm.weight')
def ids(words):
    out=[]
    for w in words:
        for v in [' '+w, w]:
            e=encode(v)
            if len(e)==1: out.append(e[0])
    return sorted(set(out))
cats={
'month':ids('January February March April May June July August September October November December'.split()),
'color':ids('red blue green yellow orange purple black white brown pink gray Red Blue Green Yellow Orange Purple Black White Brown Pink'.split()),
'french':ids('chat chien maison eau pain livre rouge pomme arbre soleil lune fromage voiture fleur oiseau ville porte fenêtre école jardin'.split()),
'digit':ids([str(i) for i in range(10)]),
'weekday':ids('Monday Tuesday Wednesday Thursday Friday Saturday Sunday'.split()),
'code':ids('def return import self print for while if elif class lambda None True False'.split()),
}
for k,v in cats.items(): print(k,len(v),[decode([i]) for i in v[:8]])
Un=U*nw  # fold norm
Un=Un/Un.norm(dim=1,keepdim=True)
dirs={k:torch.nn.functional.normalize(Un[v].mean(0),dim=0) for k,v in cats.items()}
D=torch.stack([dirs[k] for k in cats])
torch.save({'D':D,'keys':list(cats)},'/work/dirs.pt')
res={}
for L in range(20,36):
    Wd=W(f'model.language_model.layers.{L}.mlp.down_proj.weight')  # 4096 x 12288
    C=torch.nn.functional.normalize(Wd,dim=0).T@D.T  # 12288 x ncat
    line=[]
    for j,k in enumerate(cats):
        other=torch.cat([C[:,:j],C[:,j+1:]],1).abs().max(1).values
        s=C[:,j]-0.5*other
        top=s.topk(256)
        res[(L,k)]=top.indices.tolist()
        line.append(f"{k}:{C[:,j].topk(64).values.mean():.3f}")
    print(L,' '.join(line))
torch.save(res,'/work/res.pt')

